/** V7.1建物再構築の Phase 1-2（design doc §22）専用データ。ユーザー提供の間取り図を
 * 変換ツールでベクター化（SVG）したものを直接パースし、壁線の輪郭をそのまま抽出した
 * もの。最初は座標を折れ線（直線）に単純化して抽出していたが、傍聴席の丸い角などの
 * 曲線がカクカクになってしまったため、SVGの元の曲線コマンド（ベジェ曲線）をそのまま
 * 保持する方式に作り直した - 目視トレースは一切行わず、元のベクターデータの座標変換
 * （拡大縮小・Y軸反転）のみを機械的に行っているので、建物外形・壁の位置・曲線の
 * 形まで元図面と正確に一致する（scratchpad参照）。
 *
 * - Phase 1（外形）: 建物全体を1周する最も大きい輪郭の部分パスだけを取り出し、
 *   `outlinePath`として保持している。
 * - Phase 2（壁）: 各部屋の壁を構成するすべての部分パスを`wallsPath`にまとめている。
 *   面で塗ると、間取り図の色塗り部分（議会事務局）が変換ツールの都合で単色の
 *   塗りつぶしとして抽出されてしまう箇所があるため、あえて塗りつぶさず線だけを描く
 *   ことでこの問題を回避しつつ、実際の壁の太さが視覚的に分かるようにしている。
 *
 * 本庁舎1階と別館は、実際の図面上でも渡り廊下の壁でひとつづきの輪郭として描かれている
 * ため、ここでも1つの`outlinePath`・1つの`wallsPath`として扱っている（Phase 3以降で
 * 部屋・ドア・窓を追加する際に、渡り廊下の接続部で改めて分割する）。
 *
 * 壁データは元SVGの中の「壁専用の1つの大きな`<path>`要素（区画ごとに二重線で描かれた
 * 部分パスの集合）」だけを使っていたが、書庫・倉庫・印刷室・（別館の）会議室3・北國銀行
 * などいくつかの部屋の境界線と、建設課内にあるL字型の柱の記号は、その壁専用パスとは
 * 別の独立した`<path>`要素として描かれていたため、最初の抽出では見落として消えて見えて
 * いた。元図面の該当箇所と1つずつ突き合わせて特定し、壁専用パスに追加している。一方、
 * 産業課・健康福祉課・財政課・住民課（案内図で色分けされている部署）の間には、元の
 * ベクターデータ自体に境界線が存在しない（柱の記号だけがその位置にある）。ユーザーの
 * 図面にない線を勝手に描き足すことはしないという絶対ルールに従い、この区画は壁なしの
 * まま（案内図の色分けのみが根拠の、間仕切りのない一室である可能性が高い）にしている。
 *
 * これは既存の部屋・機器・案件データとは独立した、確認用プレビューでしかない
 * （design doc §24 - 既存システムには触れない）。 */

/** Phase 3: a door opening, marked by the user on a printed copy of the Phase 1-2
 * render rather than extracted from the vector data (doors turned out to be small
 * kinks baked directly into the wall outline's own path, not separable elements the
 * way pillars were). `length`/`vertical` describe the little perpendicular tick the
 * source drawing itself draws at each door. */
export interface DoorMarker {
  x: number;
  y: number;
  length: number;
  vertical: boolean;
}

/** Phase 3: a stair direction arrow, from the same user marking pass. `angleDeg`
 * follows SVG screen convention (0=right, 90=down, -90=up, 180=left). A switchback
 * staircase gets one entry per flight, tracing the walk-up path across the landing. */
export interface StairArrow {
  x: number;
  y: number;
  angleDeg: number;
}

export interface BuildingOutline {
  id: string;
  label: string;
  /** The building's own local coordinate space (image pixels, origin shifted to the
   * shape's own top-left) - used for the SVG viewBox this outline renders in. */
  viewBox: { width: number; height: number };
  /** Phase 1: the single largest subpath that traces all the way around the building,
   * as an SVG path `d` string - curves kept as curves (not flattened to polylines). */
  outlinePath: string;
  /** Phase 2: every wall-forming subpath from the source vector data, flattened into
   * one SVG path `d` string in the same local coordinate space. Rendered with stroke
   * only (no fill) so wall thickness reads as a double line without needing to work
   * around the fill-rule issue on the one color-filled room mentioned above. */
  wallsPath: string;
  /** Phase 1.5 fix: small square column (柱) symbols - these were missing from the
   * first curve-preserving pass because they live in their own separate `<path>`
   * elements in the source SVG, not inside the big wall path. Found by diffing every
   * excluded small `<path>`'s bounding box against the reference drawing. Stroke-only
   * like `wallsPath`, since the source draws each column as a thin double-line band
   * rather than a solid block. */
  pillarsPath: string;
  /** Phase 3: door openings (see {@link DoorMarker}). */
  doors: DoorMarker[];
  /** Phase 3: stair direction arrows (see {@link StairArrow}). */
  stairs: StairArrow[];
}

